<script setup lang="ts">/** * portfolio-2.vue � Studio Daida: Light Editorial Studio * slug='portfolio-2', typo='daida', palette='daida' * Fraunces italic H1, Lora body, JetBrains Mono labels * Force mode: light. Paper bg, magenta accent. */definePageMeta({ layout: false })const theme = useTemplateTheme('portfolio-2')const { styles, h1Style, h2Style, monoStyle, tpl, palette, typography } = themeuseScrollReveal('portfolio-2')const isLoaded = ref(false)onMounted(() => { setTimeout(() => { isLoaded.value = true }, 400) })const accentHex = '#C4234B'const accentSoftHex = '#F8E0E6'const activeFilter = ref('Semua')const filterOptions = ['Semua', 'Identitas', 'Web', 'Editorial', 'Pameran', 'Cetak']const visibleCount = ref(6)const caseStudies = [  { id: 1, title: 'Fragile Beauty', client: 'Museum MACAN', year: '2024', sector: 'Identitas, Pameran', desc: 'Identitas pameran seni kontemporer. Kunjungan naik 2,1x.', tags: ['Identitas', 'Pameran'] },  { id: 2, title: 'After Modernism', client: 'Galeri Nasional', year: '2023', sector: 'Identitas, Cetak', desc: 'Redesign katalog retrospektif. Penjualan naik 40%.', tags: ['Identitas', 'Cetak'] },  { id: 3, title: 'Cosmopolis', client: 'Jakarta Biennale', year: '2024', sector: 'Identitas, Web', desc: 'Identitas dan situs web biennale. 850rb kunjungan.', tags: ['Identitas', 'Web'] },  { id: 4, title: 'Daily Ritual', client: 'Commune Coffee', year: '2025', sector: 'Identitas, Editorial', desc: 'Brand system kopi spesialti. Langganan naik 18%.', tags: ['Identitas', 'Editorial'] },  { id: 5, title: 'Reopened', client: 'Tugu Kunstkring Paleis', year: '2023', sector: 'Identitas, Pameran', desc: 'Identitas pembukaan gedung heritage. Diliput Eye Magazine.', tags: ['Identitas', 'Pameran'] },  { id: 6, title: 'Currency Stories', client: 'Museum Bank Indonesia', year: '2024', sector: 'Pameran, Cetak', desc: 'Pameran tetap sejarah mata uang Indonesia.', tags: ['Pameran', 'Cetak'] },  { id: 7, title: 'Cover Redesign', client: 'Tempo Magazine', year: '2023', sector: 'Editorial', desc: 'Redesign sampul majalah. Langganan naik 22%.', tags: ['Editorial'] },  { id: 8, title: 'Origin Series', client: 'Kopi Kenangan', year: '2024', sector: 'Identitas, Cetak', desc: 'Kemasan edisi terbatas kopi single-origin. Diliput It\'s Nice That.', tags: ['Identitas', 'Cetak'] },  { id: 9, title: 'Hand-set Type', client: 'Mailing Batu', year: '2025', sector: 'Identitas', desc: 'Typeface custom studio letterpress. Diliput Print Magazine.', tags: ['Identitas'] },  { id: 10, title: 'Provenance', client: 'Bandung Design Biennale', year: '2024', sector: 'Identitas, Web', desc: 'Identitas dan platform digital bienale. 12rb pengunjung.', tags: ['Identitas', 'Web'] },  { id: 11, title: 'Modernist Auction', client: 'Sotheby\'s Indonesia', year: '2025', sector: 'Identitas', desc: 'Identitas lelang seni modernis. Diliput Wallpaper*.', tags: ['Identitas'] },  { id: 12, title: 'Reading Reborn', client: 'Gramedia', year: '2023', sector: 'Identitas', desc: 'Rebrand divisi penerbitan. Diliput Brand New.', tags: ['Identitas'] },]const filteredCases = computed(() => {  const list = activeFilter.value === 'Semua'    ? caseStudies    : caseStudies.filter(c => c.tags.includes(activeFilter.value))  return list.slice(0, visibleCount.value)})const services = [  { num: '01', title: 'Identitas Brand', desc: 'Sistem visual yang bertahan lama. Logo, tipografi, palet warna, pedoman.' },  { num: '02', title: 'Desain Editorial', desc: 'Tata letak majalah, buku, dan katalog. Konsep sampai siap cetak.' },  { num: '03', title: 'Desain Web', desc: 'Situs web dengan pertimbangan editorial. Responsif dan mudah dikelola.' },  { num: '04', title: 'Desain Pameran', desc: 'Signage, grafis dinding, dan visual untuk museum dan galeri.' },  { num: '05', title: 'Tipografi Custom', desc: 'Typeface khusus untuk brand atau proyek. Sketsa sampai font file.' },  { num: '06', title: 'Cetak & Produksi', desc: 'Pemilihan kertas, percetakan, dan finishing. Kami dampingi sampai selesai.' },]const processSteps = [  { num: '01', title: 'Percakapan', desc: 'Kami mulai dengan mendengar. Apa yang ingin Anda sampaikan, kepada siapa.' },  { num: '02', title: 'Riset & Arah', desc: 'Kami pelajari konteks Anda � pesaing, audiens, budaya. Lalu tentukan arah.' },  { num: '03', title: 'Desain & Iterasi', desc: 'Konsep dipresentasikan, masukan didengar. Dua sampai tiga putaran revisi.' },  { num: '04', title: 'Serah Terima', desc: 'File final, pedoman, dan panduan produksi. Kami bantu koordinasi vendor.' },]const conversations = [  {    name: 'Adjie Kurniawan',    role: 'Pendiri, Studio Daida',    excerpt: 'Indonesia butuh studio yang bicara pelan tapi jelas. Desain editorial soal memberi ruang pada konten, bukan mendominasinya.',    topic: 'Kembali dari Pentagram',    readTime: '12 menit',  },  {    name: 'Mira Anindya',    role: 'Direktur Editorial',    excerpt: 'Klien datang karena lelah desain yang bagus tapi tanpa substansi. Mereka ingin sesuatu yang bisa dibaca, dipahami, dan diingat.',    topic: 'Desain Editorial Indonesia',    readTime: '9 menit',  },  {    name: 'Bagas Satrio',    role: 'Tipografer',    excerpt: 'Setiap brand punya ritme tersendiri. Typeface yang baik harus menangkap ritme itu � huruf yang terasa benar saat dibaca.',    topic: 'Typeface untuk Brand Budaya',    readTime: '8 menit',  },]const klienNames = [  'Museum MACAN', 'Galeri Nasional', 'Jakarta Biennale', 'Commune Coffee',  'Tugu Kunstkring', 'Museum Bank Indonesia', 'Tempo', 'Kopi Kenangan',  'Mailing Batu', 'Bandung Biennale', 'Sotheby\'s', 'Gramedia',  'Djarum', 'BCA', 'BRI', 'Indosat',]const faqItems = [  { q: 'Berapa lama proyek biasanya selesai?', a: 'Identitas 8�12 minggu. Editorial 4�6 minggu. Estimasi pasti setelah percakapan awal.' },  { q: 'Apakah Anda hanya mengerjakan proyek budaya?', a: 'Tidak. Meskipun banyak klien kami berasal dari sektor budaya dan hospitality, kami juga mengerjakan proyek untuk brand komersial, institusi keuangan, dan perusahaan teknologi.' },  { q: 'Bagaimana cara memulai?', a: 'Kirim email ke hello@daida.id dengan deskripsi singkat tentang proyek Anda. Kami akan merespons dalam 48 jam dan menjadwalkan percakapan.' },  { q: 'Apakah Anda mengerjakan proyek di luar Bandung?', a: 'Ya. Kami mengerjakan proyek di seluruh Indonesia dan sesekali di luar negeri. Sebagian besar proses bisa dilakukan secara remote.' },]const openFaq = ref<number | null>(null)function toggleFaq(i: number) {  openFaq.value = openFaq.value === i ? null : i}const fabOpen = ref(false)const waUrl = 'https://wa.me/62227204321?text=' + encodeURIComponent('Halo, saya tertarik untuk berdiskusi tentang proyek desain.')</script><template>  <div :style="styles" class="daida-page">    <TmplNavbar      brand="Studio Daida"      wordmark="DAIDA"      :links="[        { label: 'Karya', href: '#karya' },        { label: 'Layanan', href: '#layanan' },        { label: 'Proses', href: '#proses' },        { label: 'Percakapan', href: '#percakapan' },        { label: 'Klien', href: '#klien' },        { label: 'Kontak', href: '#kontak' },      ]"      :accent="accentHex"      :bg="styles['--tmpl-bg']"      :text="styles['--tmpl-fg']"      style-variant="transparent"      force-mode="light"      :show-theme-toggle="false"    />    <!-- ============ 1. HERO + 3D ============ -->    <section id="top" class="daida-hero" :style="{ 'view-transition-name': 'hero-portfolio-2'" }>      <div class="daida-hero__canvas-wrap">        <ClientOnly>          <TmplExperienceCanvas            preset="cinematic-scroll"            :accent="accentHex"            intensity="calm"            label="Rotating DAIDA wordmark"          />        </ClientOnly>      </div>      <div class="daida-hero__content">        <div v-if="!isLoaded" class="daida-hero__skeleton">          <div class="daida-skel daida-skel--label" />          <div class="daida-skel daida-skel--h1" />          <div class="daida-skel daida-skel--body" />          <div class="daida-skel daida-skel--body daida-skel--short" />        </div>        <template v-else>          <p :style="monoStyle" class="daida-label">Vol 12, Iss 01 &middot; 2026</p>          <h1 :style="h1Style" class="daida-hero__title">            Brand, web, dan<br>editorial<br>sejak 2014.          </h1>          <p class="daida-hero__sub">            Studio desain di Bandung. Brand, web, dan editorial untuk museum, penerbit, dan brand komersial.          </p>          <p class="daida-hero__tagline">"Desain yang bercerita."</p>          <div class="daida-hero__ctas">            <a href="#karya" class="daida-btn daida-btn--primary" :style="{ background: accentHex }">Lihat karya</a>            <a href="#percakapan" class="daida-btn daida-btn--ghost">Baca percakapan</a>          </div>        </template>      </div>    </section>    <!-- ============ 2. STUDI KASUS (12 cards + filter) ============ -->    <section id="karya" class="daida-section daida-section--cases">      <div class="daida-container">        <div class="daida-section__header">          <p :style="monoStyle" class="daida-label">01 &mdash; Studi Kasus</p>          <h2 :style="h2Style" class="daida-section__title">Proyek terpilih</h2>        </div>        <div class="daida-filter">          <button            v-for="opt in filterOptions"            :key="opt"            type="button"            class="daida-filter__btn"            :class="{ 'daida-filter__btn--active': activeFilter === opt }"            :style="activeFilter === opt ? { background: accentHex, color: '#fff', borderColor: accentHex } : {}"            @click="activeFilter = opt; visibleCount = 6"          >            {{ opt }}          </button>        </div>        <div class="daida-cases-grid" data-reveal="stagger-children">          <article            v-for="(cs, i) in filteredCases"            :key="cs.id"            class="daida-case-card"          >            <div class="daida-case-card__img" :style="{ background: i % 3 === 0 ? '#F3E8FF' : i % 3 === 1 ? '#E8EEF5' : '#F5EDE4' }">              <span class="daida-case-card__img-label" :style="monoStyle">{{ cs.client }}</span>            </div>            <div class="daida-case-card__body">              <div class="daida-case-card__meta">                <span :style="monoStyle" class="daida-case-card__tags">{{ cs.sector }}</span>                <span :style="monoStyle" class="daida-case-card__year">{{ cs.year }}</span>              </div>              <h3 class="daida-case-card__title">{{ cs.title }}</h3>              <p class="daida-case-card__client">{{ cs.client }}</p>              <p class="daida-case-card__desc">{{ cs.desc }}</p>            </div>          </article>        </div>        <div v-if="filteredCases.length >= visibleCount" class="daida-more">          <button type="button" class="daida-btn daida-btn--ghost" @click="visibleCount += 6">            Lihat semua proyek          </button>        </div>      </div>    </section>    <!-- ============ 3. LAYANAN (6) ============ -->    <section id="layanan" class="daida-section daida-section--services" :style="{ background: 'var(--tmpl-surface)' }">      <div class="daida-container">        <div class="daida-section__header">          <p :style="monoStyle" class="daida-label">02 &mdash; Layanan</p>          <h2 :style="h2Style" class="daida-section__title">Apa yang kami kerjakan</h2>        </div>        <div class="daida-services-grid" data-reveal="stagger-children">          <div v-for="svc in services" :key="svc.num" class="daida-service">            <span :style="monoStyle" class="daida-service__num">{{ svc.num }}</span>            <h3 class="daida-service__title">{{ svc.title }}</h3>            <p class="daida-service__desc">{{ svc.desc }}</p>          </div>        </div>      </div>    </section>    <!-- ============ 4. PROSES (4 steps) ============ -->    <section id="proses" class="daida-section daida-section--process">      <div class="daida-container">        <div class="daida-section__header">          <p :style="monoStyle" class="daida-label">03 &mdash; Proses</p>          <h2 :style="h2Style" class="daida-section__title">Bagaimana kami bekerja</h2>        </div>        <div class="daida-process-grid" data-reveal="stagger-children">          <div v-for="step in processSteps" :key="step.num" class="daida-step">            <span :style="monoStyle" class="daida-step__num">{{ step.num }}</span>            <div class="daida-step__line" :style="{ background: accentHex }" />            <h3 class="daida-step__title">{{ step.title }}</h3>            <p class="daida-step__desc">{{ step.desc }}</p>          </div>        </div>      </div>    </section>    <!-- ============ 5. PERCAKAPAN (3 conversations) ============ -->    <section id="percakapan" class="daida-section daida-section--conversations" :style="{ background: 'var(--tmpl-surface)' }">      <div class="daida-container">        <div class="daida-section__header">          <p :style="monoStyle" class="daida-label">04 &mdash; Percakapan</p>          <h2 :style="h2Style" class="daida-section__title">Dari studio</h2>        </div>        <div class="daida-conversations-grid" data-reveal="stagger-children">          <article v-for="conv in conversations" :key="conv.name" class="daida-conversation">            <div class="daida-conversation__header">              <div class="daida-conversation__avatar" :style="{ background: accentSoftHex, color: accentHex }">                {{ conv.name.split(' ').map(w => w[0]).join('') }}              </div>              <div>                <p class="daida-conversation__name">{{ conv.name }}</p>                <p :style="monoStyle" class="daida-conversation__role">{{ conv.role }}</p>              </div>            </div>            <p class="daida-conversation__topic" :style="{ color: accentHex }">{{ conv.topic }} &middot; {{ conv.readTime }} baca</p>            <blockquote class="daida-conversation__excerpt">              &ldquo;{{ conv.excerpt }}&rdquo;            </blockquote>          </article>        </div>      </div>    </section>    <!-- ============ 6. KLIEN MARQUEE (16 names) ============ -->    <section id="klien" class="daida-section daida-section--clients">      <div class="daida-container">        <div class="daida-section__header">          <p :style="monoStyle" class="daida-label">05 &mdash; Klien</p>          <h2 :style="h2Style" class="daida-section__title">Siapa yang pernah kami bantu</h2>        </div>      </div>      <TmplMarquee        :items="klienNames"        separator="&middot;"        speed="slow"        :accent="accentHex"      />    </section>    <!-- ============ 7. FAQ ============ -->    <section id="faq" class="daida-section daida-section--faq" :style="{ background: 'var(--tmpl-surface)' }">      <div class="daida-container">        <div class="daida-section__header">          <p :style="monoStyle" class="daida-label">06 &mdash; Tanya Jawab</p>          <h2 :style="h2Style" class="daida-section__title">Pertanyaan yang sering diajukan</h2>        </div>        <div class="daida-faq-list">          <div v-for="(item, i) in faqItems" :key="i" class="daida-faq-item">            <button              type="button"              class="daida-faq-item__q"              :aria-expanded="openFaq === i"              @click="toggleFaq(i)"            >              <span>{{ item.q }}</span>              <span class="daida-faq-item__icon" :class="{ 'daida-faq-item__icon--open': openFaq === i }">+</span>            </button>            <Transition              enter-active-class="transition-all duration-300 ease-out"              leave-active-class="transition-all duration-200 ease-in"              enter-from-class="opacity-0 max-h-0"              leave-to-class="opacity-0 max-h-0"            >              <div v-if="openFaq === i" class="daida-faq-item__a">                <p>{{ item.a }}</p>              </div>            </Transition>          </div>        </div>      </div>    </section>    <!-- ============ 8. KONTAK / FOOTER ============ -->    <section id="kontak" class="daida-section daida-section--contact">      <div class="daida-container">        <div class="daida-contact-grid" data-reveal="stagger-children">          <div class="daida-contact__info">            <p :style="monoStyle" class="daida-label">07 &mdash; Hubungi Kami</p>            <h2 :style="h2Style" class="daida-section__title">Ceritakan proyek Anda</h2>            <p class="daida-contact__text">Kami merespons dalam 48 jam.</p>            <div class="daida-contact__details">              <p><strong>Email</strong><br><a href="mailto:hello@daida.id" :style="{ color: accentHex }">hello@daida.id</a></p>              <p><strong>Telepon</strong><br>+62 22 720 4321</p>              <p><strong>Alamat</strong><br>Jl. Lombok No. 12<br>Bandung 40114, Indonesia</p>              <p><strong>Jam Kerja</strong><br>Senin&ndash;Jumat, 09.00&ndash;18.00 WIB</p>            </div>          </div>          <div class="daida-contact__form-wrap">            <TmplForm              :fields="[                { key: 'name', label: 'Nama', required: true },                { key: 'email', label: 'Email', type: 'email', required: true },                { key: 'company', label: 'Perusahaan' },                { key: 'type', label: 'Jenis Proyek', type: 'select', options: ['Identitas', 'Editorial', 'Web', 'Pameran', 'Tipografi', 'Lainnya'] },                { key: 'message', label: 'Ceritakan proyek Anda', type: 'textarea', required: true },              ]"              submit-label="Kirim Pesan"              :accent="accentHex"              whatsapp-phone="62227204321"              whatsapp-message-prefix="Halo, saya ingin berdiskusi tentang proyek:"            />          </div>        </div>      </div>    </section>    <TmplFooter data-reveal="fade-up" brand-name="Studio Daida"      variant="columns"      :links="[        { label: 'Karya', href: '#karya' },        { label: 'Layanan', href: '#layanan' },        { label: 'Proses', href: '#proses' },        { label: 'Percakapan', href: '#percakapan' },        { label: 'Kontak', href: '#kontak' },      ]"      :accent="accentHex"      :bg="styles['--tmpl-surface']"      :text="styles['--tmpl-fg']"      signature="Bandung, Indonesia"    />    <!-- WhatsApp FAB -->    <div class="daida-fab">      <Transition enter-active-class="transition-all duration-300 ease-out" leave-active-class="transition-all duration-200 ease-in" enter-from-class="opacity-0 translate-y-4 scale-95" leave-to-class="opacity-0 translate-y-4 scale-95">        <div v-if="fabOpen" class="daida-fab__popup">          <p class="daida-fab__title">Tertarik bekerja sama?</p>          <p class="daida-fab__text">Chat langsung untuk diskusi proyek Anda.</p>          <a :href="waUrl" target="_blank" rel="noopener" class="daida-fab__wa" :style="{ background: accentHex }">            Chat WhatsApp          </a>        </div>      </Transition>      <button :style="{ background: accentHex }" class="daida-fab__btn" @click="fabOpen = !fabOpen" aria-label="Hubungi via WhatsApp">        <svg class="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.521.149-.174.198-.298.298-.497.099-.198.05-.372-.025-.521-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.501-.669-.51l-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.626.712.227 1.36.195 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m